CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), phone TEXT UNIQUE NOT NULL, name TEXT NOT NULL DEFAULT 'Family member', sharing_enabled BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS invitations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), inviter_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, invited_phone TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL DEFAULT now()+interval '7 days', accepted_at TIMESTAMPTZ, declined_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS shares (subject_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, viewer_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, consented_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(subject_id,viewer_id), CHECK(subject_id<>viewer_id));
CREATE TABLE IF NOT EXISTS latest_locations (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, lat DOUBLE PRECISION NOT NULL, lng DOUBLE PRECISION NOT NULL, accuracy DOUBLE PRECISION, battery SMALLINT, recorded_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS history (id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, lat DOUBLE PRECISION NOT NULL, lng DOUBLE PRECISION NOT NULL, accuracy DOUBLE PRECISION, battery SMALLINT, recorded_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS history_user_time ON history(user_id,recorded_at DESC);
CREATE TABLE IF NOT EXISTS zones (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), owner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, lat DOUBLE PRECISION NOT NULL, lng DOUBLE PRECISION NOT NULL, radius_m INTEGER NOT NULL CHECK(radius_m BETWEEN 100 AND 2000), created_by UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS zone_presence (zone_id UUID PRIMARY KEY REFERENCES zones(id) ON DELETE CASCADE, inside BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS alerts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), viewer_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, subject_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, message TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS alerts_time ON alerts(viewer_id,created_at DESC);
